function exactHit(name, list) {
	var n = String(name || '');
	return (list || []).some(function(m) { return m && n.indexOf(m) !== -1; });
}

function hideTokens(names, exact) {
	var hit = exact ? exactHit : exclHit;
	var rxFlag, rxPic, rxWord;
	try {
