			items = items.filter(function(it) { return !it.gone || names.indexOf(it.name) >= 0; });
			items.forEach(function(it) { it.hidden = names.indexOf(it.name) >= 0; it.locked = !it.hidden && keep.length > 0 && hit(it.name, keep); });
			stop();
