				zm.steerAction('catalog_refresh', '').then(function(res) {
					if (res.error) { zm.toast(res.error, 'error'); return; }
					zm.toast('Обновляем каталог', 'info');
					setTimeout(refresh, 5000);
				}).catch(function() { zm.toast('Роутер не ответил', 'error'); });
			} }, 'Обновить'));
