			b.push(E('button', { 'class': 'cbi-button', 'click': function() {
				zm.steerAction('catalog_src', c.off ? 'on' : 'off').then(function(res) {
					if (res.error) { zm.toast(res.error, 'error'); return; }
					refresh();
				}).catch(function() { zm.toast('Роутер не ответил', 'error'); });
