							if (busy) { zm.toast('Дождитесь завершения текущей операции', 'warning'); return; }
							if (current === it.id) return;
							busy = true;
							zm.toast('Применяем стратегию ' + it.id + '', 'warning');
							zm.strategySetYoutube(it.id).then(function(r2) {
								busy = false;
