			]);

			var fakeCard = E('div', { 'class': 'zm-card' }, [
				E('h3', {}, 'Fake-файл для discord,stun'),
				fakeGrid,
				E('p', { 'class': 'zm-hint' }, 'Работает, только когда включена стратегия Discord.')
			]);

			panels.discord.appendChild(dvCard);
			panels.discord.appendChild(fakeCard);
