function dnsLabel(d) {
	if (!d) return '—';
	var sv = d.servers && d.servers.length ? d.servers : [ d.server ];
	var cur = sv[d.active > 0 && d.active < sv.length ? d.active : 0];
	return dnsName(d.type, cur) + (sv.length > 1 ? ' +' + (sv.length - 1) : '');
