			var autoTag = list.filter(function(t) { return ns[t] && ns[t].members; })[0], auto = autoTag ? ns[autoTag] : null;
			var isAuto = !!(autoTag && servers.now === autoTag);
			var curTag = isAuto ? auto.now : servers.now;
